TALL = '맨 아랫줄(밑동)만 막히고 위 칸은 걷기+가림(뒤로 지나간다).'
def M(src, kind, ko, desc, rules, brows=None, role=None, layer=None, soft=False):
    d = dict(src=src, kind=kind, ko=ko, desc=desc, rules=rules, soft=soft)
    if brows is not None: d['brows'] = brows
    if role: d['role'] = role
    if layer: d['layer'] = layer
    return d
def R(src, brows=1, kind='object', soft=False):
    return dict(src=src, kind=kind, brows=brows, reuse=True, soft=soft)

